choose.usage:
echo 'one two three' | choose 0 # Select first field (zero-indexed)
echo 'one two three four' | choose 1:3 # Select fields 1-2 (slice notation)
echo 'one two three' | choose -1 # Select last field (negative indexing)
echo 'a:b:c:d' | choose -f ':' 1 3 # Custom separator and multiple fields
